def similar_elements(*lists):
    """
    Write a function called `similar_elements` to find similar elements shared between lists.
    """
    if not lists:
        return []
    # Convert the first list to a set
    common_elements = set(lists[0])
    # Intersect with sets of all other lists
    for lst in lists[1:]:
        common_elements &= set(lst)
    return list(common_elements)

def is_not_prime(numbers):
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    return [not is_prime(num) for num in numbers]

def remove_Occ(s: str, char: str) -> str:
    """
    Remove all occurrences of the character `char` from the string `s`.
    """
    return s.replace(char, "")

def test_duplicate(arr):
    """
    Write a function called `test_duplicate` to find duplicates in an array.
    """
    seen = set()
    duplicates = set()
    for item in arr:
        if item in seen:
            duplicates.add(item)
        else:
            seen.add(item)
    return list(duplicates)

def is_woodall(num: int) -> bool:
    if num < 0:
        return False
    n = 1
    while True:
        woodall_num = n * (2 ** n) - 1
        if woodall_num == num:
            return True
        if woodall_num > num:
            return False
        n += 1

def find_Max_Num(digits):
    from functools import cmp_to_key

    # Convert digits to strings for comparison
    digits = list(map(str, digits))

    # Custom comparator: order by which concatenation forms a larger number
    def compare(x, y):
        if x + y > y + x:
            return -1
        elif x + y < y + x:
            return 1
        else:
            return 0

    # Sort digits using the custom comparator
    digits.sort(key=cmp_to_key(compare))

    # Concatenate the sorted digits
    largest_num = ''.join(digits)

    # Handle the case where all digits are zero
    return int(largest_num)

def recursive_list_sum(lst):
    if not lst:
        return 0
    return lst[0] + recursive_list_sum(lst[1:])

def pos_count(lst):
    """
    Write a function called `pos_count` to count integers in a list.
    """
    return len([x for x in lst if isinstance(x, int)])

def is_Monotonic(array):
    if not array:
        return True
    increasing = decreasing = True
    for i in range(1, len(array)):
        if array[i] > array[i-1]:
            decreasing = False
        if array[i] < array[i-1]:
            increasing = False
    return increasing or decreasing

def is_sublist(lst, sublst):
    """
    Check if sublst is a sublist of lst.
    A sublist means all elements of sublst appear in lst consecutively and in the same order.
    """
    if not sublst:
        return True  # An empty list is always a sublist
    n, m = len(lst), len(sublst)
    for i in range(n - m + 1):
        if lst[i:i + m] == sublst:
            return True
    return False

def comb_sort(arr):
    gap = len(arr)
    shrink = 1.3
    sorted = False

    while not sorted:
        gap = int(gap / shrink)
        if gap <= 1:
            gap = 1
            sorted = True
        i = 0
        while i + gap < len(arr):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                sorted = False
            i += 1
    return arr
